from pathlib import Path

p = Path('scripts/process-game-action.ts')
s = p.read_text(encoding='utf-8')
s = s.replace("import {\n  createParticipant,\n  strengthenTronco,\n  transferSeeds\n} from '../src/services/gameEngine';", "import {\n  createParticipant,\n  strengthenTronco,\n  transferSeeds,\n  TOPOLOGY\n} from '../src/services/gameEngine';", 1)
s = s.replace("action: 'register_participant' | 'strengthen_tronco' | 'transfer_seeds';", "action: 'register_participant' | 'strengthen_tronco' | 'transfer_seeds' | 'create_tree' | 'archive_tree' | 'assign_tree_position' | 'clear_tree_position';", 1)
s = s.replace("  const requestActor = process.env.GITHUB_REQUEST_ACTOR || process.env.GITHUB_ACTOR || null;\n\n  let resultState: GameDatabaseState;", "  const requestActor = process.env.GITHUB_REQUEST_ACTOR || process.env.GITHUB_ACTOR || null;\n\n  const cloneState = () => JSON.parse(JSON.stringify(state)) as GameDatabaseState;\n  const nextId = (items: Array<{ id: number }>) => Math.max(0, ...items.map(item => item.id)) + 1;\n  const nowIso = () => new Date().toISOString();\n  const adminActions = ['create_tree', 'archive_tree', 'assign_tree_position', 'clear_tree_position'];\n\n  if (adminActions.includes(payload.action)) {\n    const owner = process.env.GITHUB_REPOSITORY_OWNER || '';\n    const configured = (process.env.ADMIN_GITHUB_ACTORS || '').split(',').map(v => v.trim()).filter(Boolean);\n    const allowed = new Set([owner, ...configured].filter(Boolean));\n    if (!requestActor || !allowed.has(requestActor)) {\n      console.error(`ERRO: @${requestActor || 'desconhecido'} não está autorizado para ações administrativas.`);\n      process.exit(1);\n    }\n  }\n\n  const appendAudit = (target: GameDatabaseState, action: string, entity: string, entityId: number | string, metadata: Record<string, any>) => {\n    target.auditLog.push({\n      id: nextId(target.auditLog),\n      actorUserId: 1,\n      actorUsername: 'admin',\n      action,\n      entity,\n      entityId,\n      metadata: { ...metadata, githubActor: requestActor, idempotencyKey: payload.idempotencyKey },\n      createdAt: nowIso()\n    });\n  };\n\n  let resultState: GameDatabaseState;", 1)
cases = '''\n\n    case 'create_tree': {\n      const result = cloneState();\n      const categoryId = Number(payload.params.categoryId);\n      const troncoUserId = Number(payload.params.troncoUserId);\n      const category = result.config.categories.find(c => c.id === categoryId && c.isActive);\n      const tronco = result.users.find(u => u.id === troncoUserId && u.status === 'active');\n      if (!category) { console.error('ERRO: Categoria inválida ou inativa.'); process.exit(1); }\n      if (!tronco) { console.error('ERRO: Membro tronco inválido ou inativo.'); process.exit(1); }\n      const newTreeId = Math.max(0, ...result.trees.map(t => t.id)) + 1;\n      const now = nowIso();\n      result.trees.push({\n        id: newTreeId, categoryId, treeCode: `ARB-TREE-${category.tokenRequirement}-${String(newTreeId).padStart(3, '0')}`,\n        troncoUserId, status: 'active', cycleNumber: 1, parentTreeId: null,\n        positions: TOPOLOGY.map(topo => topo.index === 0 ? {\n          index: 0, level: 0, side: topo.side, userId: tronco.id, status: 'occupied', occupiedAt: now, username: tronco.username, name: tronco.name\n        } : {\n          index: topo.index, level: topo.level, side: topo.side, userId: null, status: 'vacant', occupiedAt: null, username: null, name: null\n        }),\n        createdAt: now, completedAt: null\n      });\n      result.referrals.push({\n        id: nextId(result.referrals), referrerUserId: troncoUserId, referredUserId: null, treeId: newTreeId,\n        token: `ref_arb_tree_${newTreeId}_${Math.random().toString(36).slice(2, 10)}`,\n        clicks: 0, registrationsCount: 0, isActive: true, createdAt: now\n      });\n      tronco.currentTreeId = newTreeId;\n      tronco.currentPositionIndex = 0;\n      tronco.updatedAt = now;\n      appendAudit(result, 'ADMIN_TREE_CREATED', 'tree', newTreeId, { categoryId, troncoUserId });\n      resultState = result;\n      commitMessage = `[game-data] criar árvore administrativa #${newTreeId}`;\n      break;\n    }\n\n    case 'archive_tree': {\n      const result = cloneState();\n      const treeId = Number(payload.params.treeId);\n      const tree = result.trees.find(t => t.id === treeId);\n      if (!tree || tree.status !== 'active') { console.error('ERRO: Árvore ativa não encontrada.'); process.exit(1); }\n      const reason = String(payload.params.reason || 'Arquivamento administrativo');\n      const now = nowIso();\n      tree.status = 'archived';\n      tree.completedAt = tree.completedAt || now;\n      for (const ref of result.referrals.filter(r => r.treeId === treeId)) ref.isActive = false;\n      for (const pos of tree.positions.filter(p => p.status === 'occupied' && p.userId !== null)) {\n        const user = result.users.find(u => u.id === pos.userId);\n        if (user?.currentTreeId === treeId) { user.currentTreeId = null; user.currentPositionIndex = null; user.updatedAt = now; }\n      }\n      appendAudit(result, 'ADMIN_TREE_ARCHIVED', 'tree', treeId, { reason });\n      resultState = result;\n      commitMessage = `[game-data] arquivar árvore #${treeId}`;\n      break;\n    }\n\n    case 'assign_tree_position': {\n      const result = cloneState();\n      const treeId = Number(payload.params.treeId);\n      const positionIndex = Number(payload.params.positionIndex);\n      const userId = Number(payload.params.userId);\n      const tree = result.trees.find(t => t.id === treeId && t.status === 'active');\n      const user = result.users.find(u => u.id === userId && u.status === 'active');\n      if (!tree) { console.error('ERRO: Árvore ativa não encontrada.'); process.exit(1); }\n      if (!user) { console.error('ERRO: Membro ativo não encontrado.'); process.exit(1); }\n      const pos = tree.positions.find(p => p.index === positionIndex);\n      if (!pos) { console.error('ERRO: Posição inexistente.'); process.exit(1); }\n      if (pos.status === 'occupied' && pos.userId !== userId) { console.error('ERRO: Posição já ocupada. Libere a posição antes.'); process.exit(1); }\n      const otherTree = result.trees.find(t => t.id !== treeId && t.status === 'active' && t.positions.some(p => p.userId === userId && p.status === 'occupied'));\n      if (otherTree) { console.error('ERRO: Membro já ocupa posição em outra árvore ativa.'); process.exit(1); }\n      const now = nowIso();\n      for (const oldPos of tree.positions.filter(p => p.userId === userId)) { oldPos.userId = null; oldPos.username = null; oldPos.name = null; oldPos.status = 'vacant'; oldPos.occupiedAt = null; }\n      pos.userId = user.id; pos.username = user.username; pos.name = user.name; pos.status = 'occupied'; pos.occupiedAt = now;\n      user.currentTreeId = treeId; user.currentPositionIndex = positionIndex; user.updatedAt = now;\n      appendAudit(result, 'ADMIN_POSITION_ASSIGNED', 'tree_position', `${treeId}:${positionIndex}`, { treeId, positionIndex, userId });\n      resultState = result;\n      commitMessage = `[game-data] posicionar @${user.username} na árvore #${treeId}`;\n      break;\n    }\n\n    case 'clear_tree_position': {\n      const result = cloneState();\n      const treeId = Number(payload.params.treeId);\n      const positionIndex = Number(payload.params.positionIndex);\n      const tree = result.trees.find(t => t.id === treeId && t.status === 'active');\n      if (!tree) { console.error('ERRO: Árvore ativa não encontrada.'); process.exit(1); }\n      const pos = tree.positions.find(p => p.index === positionIndex);\n      if (!pos || pos.status !== 'occupied' || pos.userId === null) { console.error('ERRO: Posição ocupada não encontrada.'); process.exit(1); }\n      const user = result.users.find(u => u.id === pos.userId);\n      const removedUserId = pos.userId;\n      const now = nowIso();\n      pos.userId = null; pos.username = null; pos.name = null; pos.status = 'vacant'; pos.occupiedAt = null;\n      if (user?.currentTreeId === treeId && user.currentPositionIndex === positionIndex) { user.currentTreeId = null; user.currentPositionIndex = null; user.updatedAt = now; }\n      appendAudit(result, 'ADMIN_POSITION_CLEARED', 'tree_position', `${treeId}:${positionIndex}`, { treeId, positionIndex, removedUserId });\n      resultState = result;\n      commitMessage = `[game-data] liberar posição #${positionIndex} da árvore #${treeId}`;\n      break;\n    }'''
s = s.replace("\n    default:\n      console.error(`Ação desconhecida: ${(payload as any).action}`);", cases + "\n\n    default:\n      console.error(`Ação desconhecida: ${(payload as any).action}`);", 1)
p.write_text(s, encoding='utf-8')

p = Path('.github/workflows/process-game-issue.yml')
s = p.read_text(encoding='utf-8')
s = s.replace("const allowed = new Set(['register_participant', 'strengthen_tronco']);", "const allowed = new Set(['register_participant', 'strengthen_tronco', 'create_tree', 'archive_tree', 'assign_tree_position', 'clear_tree_position']);", 1)
s = s.replace("          GITHUB_REQUEST_ACTOR: ${{ github.event.issue.user.login }}\n        run: |", "          GITHUB_REQUEST_ACTOR: ${{ github.event.issue.user.login }}\n          GITHUB_REPOSITORY_OWNER: ${{ github.repository_owner }}\n        run: |", 1)
p.write_text(s, encoding='utf-8')
print('step b ok')
